<?php
declare(strict_types=1);
require_once __DIR__.'/BusinessContactVisibility.php';
/** Fixed fictitious content, rendered by the production views. Never loads draft businesses. */
function businessDemo(PDO $pdo,string $plan):array
{
    if(!in_array($plan,['free','featured','page','page_premium'],true))throw new RuntimeException('Ejemplo no disponible.');
    $q=$pdo->prepare('SELECT feature_code FROM subscription_plan_features WHERE plan_code=? AND included=1');$q->execute([$plan]);$features=array_fill_keys($q->fetchAll(PDO::FETCH_COLUMN),true);
    $media=static fn($file)=>['asset_path'=>'assets/'.$file,'alt_text'=>'Ilustración de ejemplo; no es una fotografía del negocio','width'=>1536,'height'=>1024,'caption'=>'Imagen ilustrativa de ejemplo'];
    $business=['id'=>0,'public_id'=>'00000000-0000-4000-8000-'.str_pad((string)array_search($plan,['free','featured','page','page_premium']),12,'0',STR_PAD_LEFT),'slug'=>'negocio-ejemplo','display_name'=>'Zunaria Casa De Niebla','summary'=>'Un refugio entre sabores, descanso y caminos por descubrir. Hospedaje tranquilo y cocina de temporada en Medellín.','description'=>'Aquí el negocio presenta su oferta con el espacio disponible en su suscripción. Puede explicar sus productos, servicios y lo que el viajero necesita saber antes de visitarlo. Este establecimiento es un ejemplo, no un negocio real.','brand_story'=>$plan==='page_premium'?'Esta sección permite contar la trayectoria y la identidad del negocio. Forma parte de la presentación ampliada de Premium.':'','featured_services'=>$plan==='page_premium'?'Aquí se describen los servicios que el negocio quiere resaltar, con su propio espacio de contenido.':'','plan_code'=>$plan,'plan_name'=>['free'=>'Gratis','featured'=>'Destacado','page'=>'Página Comercial','page_premium'=>'Premium'][$plan],'features'=>$features,'code'=>'hospedaje','category_code'=>'hospedaje','category_label'=>'Hospedaje','category_labels'=>['Hospedaje'],'category_codes'=>['hospedaje'],'destination_slug'=>'jerico','department'=>'Antioquia','country_code'=>'CO','information_status'=>'PUBLICO','operation_status'=>'ABIERTO','address_text'=>'Ubicación de ejemplo','location_reference'=>'Datos demostrativos, sin dirección real','latitude'=>null,'longitude'=>null,'location_map_url'=>'https://www.google.com/maps/search/?api=1&query=Medellin%20Colombia','opening_hours'=>'','price_range'=>'consultar','capacity_count'=>null,'menu_url'=>'','reservations_url'=>'','contacts'=>[],'logo'=>null,'cover'=>in_array($plan,['page','page_premium'],true)?$media('planes-negocio-editorial-v1.webp'):null,'gallery'=>[],'image_path'=>null,'width'=>null,'height'=>null,'demo_page_url'=>'/business/demo.php?view='.$plan];
    $channels=['phone'=>'+573234870366','whatsapp'=>'+573234870366','email'=>'contacto@explorandolugares.com','instagram'=>'https://www.instagram.com/explorandolugaresco/','website'=>'https://explorandolugares.com/'];
    $business['contacts']=BusinessContactVisibility::filter($plan,array_map(static fn($channel,$value)=>['channel'=>$channel,'contact_value'=>$value,'is_public'=>1],array_keys($channels),array_values($channels)));
    $business['showcase']=['products'=>[],'experiences'=>[]];
    if($plan==='page_premium'){$business['category_codes']=['hospedaje','alimentacion'];$business['category_labels']=['Hospedaje','Restaurante'];foreach(['Nube De Cacao','Mesa Viajera','Nido Zunaria','Fogón de montaña','Ritual de descanso'] as $i=>$name)$business['showcase']['products'][]=['name'=>$name,'description'=>'Una propuesta de ejemplo para mostrar el producto o servicio estrella del negocio.','asset_path'=>'assets/'.(['planes-negocio-editorial-v1.webp','proceso-negocio-editorial-v1.webp','valor-negocios-editorial-v1.webp'][$i%3])];}
    return $business;

}
